function validate([packages, boxes]) {
  if (!Array.isArray(packages) || packages.length < 1 || packages.length > 100000) return 'packages needs 1 to 10^5 values.';
  if (packages.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each package size is between 1 and 10^5.';
  if (!Array.isArray(boxes) || boxes.length < 1 || boxes.length > 100000) return 'boxes needs 1 to 10^5 suppliers.';
  let total = 0;
  for (const sizes of boxes) {
    if (!Array.isArray(sizes) || sizes.length < 1) return 'Every supplier sells at least one box size.';
    if (sizes.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each box size is between 1 and 10^5.';
    if (new Set(sizes).size !== sizes.length) return "A supplier's box sizes must be distinct.";
    total += sizes.length;
  }
  if (total > 100000) return 'All suppliers together list at most 10^5 box sizes.';
  return null;
}

