function minWastedSpace(packages, boxes) {
  const MOD = 1000000007;
  packages.sort((a, b) => a - b);
  const n = packages.length;
  const packageSum = packages.reduce((sum, size) => sum + size, 0);
  let best = Infinity;

  for (const sizes of boxes) {
    sizes.sort((a, b) => a - b);
    if (sizes[sizes.length - 1] < packages[n - 1]) {
      continue;
    }
    let boxSpace = 0;
    let packed = 0;
    for (const size of sizes) {
      let low = packed;
      let high = n;
      while (low < high) {
        const mid = (low + high) >> 1;
        if (packages[mid] <= size) {
          low = mid + 1;
        } else {
          high = mid;
        }
      }
      boxSpace += size * (low - packed);
      packed = low;
    }
    best = Math.min(best, boxSpace - packageSum);
  }
  return best === Infinity ? -1 : best % MOD;
}

