function minWastedSpace(packages, boxes) {
  // For every supplier, give each package the smallest box that fits it.
  let best = -1;
  for (const supplier of boxes) {
    let waste = 0;
    let ok = true;
    for (const p of packages) {
      let smallest = Infinity;
      for (const b of supplier) if (b >= p && b < smallest) smallest = b;
      if (smallest === Infinity) { ok = false; break; }
      waste += smallest - p;
    }
    if (ok && (best === -1 || waste < best)) best = waste;
  }
  return best === -1 ? -1 : best % 1000000007;
}

