function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const distinct = (count, top) => {
    const seen = new Set();
    while (seen.size < Math.min(count, top)) seen.add(int(1, top));
    return [...seen];
  };
  if (size === 'large') {
    const top = 100000;
    const packages = Array.from({ length: int(1900, 2000) }, () => int(1, top));
    const m = int(20, 60);
    const boxes = [];
    for (let j = 0; j < m; j++) {
      const sizes = distinct(int(1, 60), top);
      // Most suppliers can fit the largest package.
      if (rand() < 0.8 && !sizes.includes(top)) sizes.push(top);
      boxes.push(sizes);
    }
    return [packages, boxes];
  }
  const top = rand() < 0.5 ? 8 : 25;
  const packages = Array.from({ length: int(1, 6) }, () => int(1, top));
  const m = int(1, 4);
  const boxes = [];
  for (let j = 0; j < m; j++) boxes.push(distinct(int(1, 4), top));
  return [packages, boxes];
}
